import React, { useEffect, useState } from 'react';
import API from '../api/axios';

const LostFoundPage = () => {
  const [items, setItems] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [formData, setFormData] = useState({
    type: 'Lost', itemName: '', description: '', location: '', contact: ''
  });
  const [file, setFile] = useState(null);

  const fetchItems = () => {
    API.get('/lostfound')
      .then(res => setItems(res.data))
      .catch(err => console.error(err));
  };

  useEffect(() => { fetchItems(); }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    const data = new FormData();
    Object.keys(formData).forEach(key => data.append(key, formData[key]));
    if (file) data.append('image', file);

    try {
      await API.post('/lostfound', data, { headers: { 'Content-Type': 'multipart/form-data' } });
      alert('Post created!');
      setShowForm(false);
      fetchItems();
    } catch (err) {
      alert('Failed to post item.');
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 space-y-6">
      <div className="flex justify-between items-center">
        <h1 className="text-2xl font-bold text-slate-900">Campus Lost & Found Bulletin</h1>
        <button
          onClick={() => setShowForm(!showForm)}
          className="bg-sky-600 text-white px-4 py-2 rounded-lg font-semibold hover:bg-sky-700 transition"
        >
          {showForm ? 'Cancel' : 'Post Item'}
        </button>
      </div>

      {showForm && (
        <form onSubmit={handleSubmit} className="bg-white p-6 rounded-xl shadow-md border space-y-4 max-w-xl mx-auto">
          <h3 className="text-lg font-bold">New Lost/Found Item Notice</h3>
          <div className="grid grid-cols-2 gap-4">
            <select
              className="p-2 border rounded"
              value={formData.type}
              onChange={(e) => setFormData({ ...formData, type: e.target.value })}
            >
              <option>Lost</option>
              <option>Found</option>
            </select>
            <input
              type="text" placeholder="Item Name" required className="p-2 border rounded"
              value={formData.itemName} onChange={(e) => setFormData({ ...formData, itemName: e.target.value })}
            />
          </div>
          <input
            type="text" placeholder="Location" required className="w-full p-2 border rounded"
            value={formData.location} onChange={(e) => setFormData({ ...formData, location: e.target.value })}
          />
          <input
            type="text" placeholder="Contact Details (Phone / Email)" required className="w-full p-2 border rounded"
            value={formData.contact} onChange={(e) => setFormData({ ...formData, contact: e.target.value })}
          />
          <textarea
            placeholder="Detailed description..." required className="w-full p-2 border rounded"
            value={formData.description} onChange={(e) => setFormData({ ...formData, description: e.target.value })}
          />
          <input type="file" accept="image/*" onChange={(e) => setFile(e.target.files[0])} />
          <button type="submit" className="w-full bg-emerald-600 text-white py-2 rounded font-bold hover:bg-emerald-700">
            Publish Post
          </button>
        </form>
      )}

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {items.map((item) => (
          <div key={item._id} className="bg-white rounded-xl shadow border overflow-hidden flex flex-col justify-between">
            <div className="p-5">
              <div className="flex justify-between items-center mb-2">
                <span className={`px-2.5 py-1 text-xs font-extrabold uppercase rounded ${item.type === 'Lost' ? 'bg-red-100 text-red-700' : 'bg-emerald-100 text-emerald-700'}`}>
                  {item.type}
                </span>
                <span className="text-xs text-slate-400">{new Date(item.createdAt).toLocaleDateString()}</span>
              </div>
              <h3 className="font-bold text-lg text-slate-800">{item.itemName}</h3>
              <p className="text-sm text-slate-600 mt-2">{item.description}</p>
              <p className="text-xs text-slate-500 mt-3">📍 {item.location}</p>
              <p className="text-xs text-slate-500">📞 {item.contact}</p>
            </div>
            {item.image && (
              <img src={`http://localhost:5000${item.image}`} alt={item.itemName} className="h-40 w-full object-cover" />
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default LostFoundPage;
